def compute(vars):
    amount_usd = vars["v1"] * 1000000
    shares = vars["v2"]
    if shares == 0:
        return None
    value = amount_usd / shares
    return {
        "value": value,
        "trace": {
            "amount_usd": amount_usd,
            "shares": shares,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "USD per share"
            }
        }
    }
